<?php

namespace App\Index\Controllers;

use Core\Controller;
use Core\Db;

class IndexController extends Controller
{
  public function getDaily(): void
  {
    $today = date('z') + 1;
    $result = Db::name('tb_daily')
      ->where('id', '=', $today)
      ->select();
    $result = $this->decodeFields($result, ['cn', 'en']);
    $this->json($result);
  }

  public function getArticle(): void
  {
    $result = Db::name('tb_article')->select();
    $result = $this->decodeFields($result, ['title', 'subtitle', 'summary', 'content']);
    $this->json($result);
  }

  public function getInfo(): void
  {
    $result =  [
      'today' => date('z') + 1,
      'photo' => 'data:image/png;base64,',
      'note' => '会点设计，会点前端，会点后端的程序猿。'
    ];
    $this->json($result);
  }

  public function getDetail(): void
  {
    $id = $this->input('post.id/d', 1);

    if ($id <= 0) {
      $this->json([], 'ID参数错误', 0);
      return;
    }

    try {
      Db::name('tb_article')
        ->where('id', '=', $id)
        ->inc('hits')
        ->update();

      $result = Db::name('tb_article')
        ->where('id', '=', $id)
        ->select();

      if (empty($result)) {
        $this->json([], '文章不存在', 0);
        return;
      }

      $result = $this->decodeFields($result, ['title', 'subtitle', 'summary', 'content']);
      $this->json($result[0]);
      return;
    } catch (\Exception $e) {
      $this->json([], '获取文章详情失败', 0);
      return;
    }
  }
}
